#!/bin/sh
# AUTO-GENERATED by scripts/build_installers.py from scripts/modules/ — DO NOT EDIT MANUALLY.
set -e

# CubeX iStoreOS / OpenWrt Self-Extracting .run Installer Module (Strict POSIX sh / ash)
# Zero bashisms: no [[, no declare, no source, no local, no arrays, no &>, no <<<.

CUBEX_RUN_VERSION="v9.994"
CUBEX_RUN_ARCH="@@CUBEX_ARCH@@"
CUBEX_PAYLOAD_SHA256="@@CUBEX_PAYLOAD_SHA256@@"
CUBEX_PAYLOAD_SIZE="@@CUBEX_PAYLOAD_SIZE@@"

INSTALL_DIR="/opt/cubex"
APP_PORT="2026"
ACTION_MODE="install"
EXTRACT_DIR=""
FORCE_ARCH=0
AUTO_CONFIRM=1

istore_msg() {
    printf '%s\n' "$*"
}

istore_err() {
    printf '%s\n' "$*" >&2
}

istore_usage() {
    istore_msg "CubeX iStoreOS / OpenWrt Self-Extracting Installer (${CUBEX_RUN_VERSION}, ${CUBEX_RUN_ARCH})"
    istore_msg "Usage: sh $0 [options]"
    istore_msg "  --dir=<path>       Install directory (default: /opt/cubex)"
    istore_msg "  --port=<port>      Web dashboard port (default: 2026)"
    istore_msg "  --check | --info   Verify embedded SHA256 and architecture without installing"
    istore_msg "  --extract=<dir>    Extract payload archive contents to <dir> only"
    istore_msg "  --uninstall        Run uninstall.sh to cleanly remove CubeX"
    istore_msg "  --force-arch       Bypass CPU architecture mismatch check"
    istore_msg "  -y | --yes         Non-interactive installation (default)"
    istore_msg "  -h | --help        Show this help message"
}

for _ir_arg in "$@"; do
    case "$_ir_arg" in
        --dir=*)
            INSTALL_DIR="${_ir_arg#*=}"
            ;;
        --port=*)
            APP_PORT="${_ir_arg#*=}"
            ;;
        --check|--info)
            ACTION_MODE="check"
            ;;
        --extract=*)
            ACTION_MODE="extract"
            EXTRACT_DIR="${_ir_arg#*=}"
            ;;
        --uninstall)
            ACTION_MODE="uninstall"
            ;;
        --force-arch)
            FORCE_ARCH=1
            ;;
        -y|--yes|--silent)
            AUTO_CONFIRM=1
            ;;
        -h|--help)
            istore_usage
            exit 0
            ;;
        *)
            istore_err "Unknown option: $_ir_arg"
            istore_usage
            exit 1
            ;;
    esac
done

if [ "$ACTION_MODE" = "uninstall" ]; then
    if [ "$(id -u)" -ne 0 ]; then
        istore_err "Error: uninstall requires root privileges."
        exit 1
    fi
    if [ -x "${INSTALL_DIR}/uninstall.sh" ]; then
        exec sh "${INSTALL_DIR}/uninstall.sh"
    elif [ -x "/opt/cubex/uninstall.sh" ]; then
        exec sh "/opt/cubex/uninstall.sh"
    else
        istore_err "Error: uninstall.sh not found in ${INSTALL_DIR} or /opt/cubex."
        exit 1
    fi
fi

_SELF_PATH="$0"
if [ ! -f "$_SELF_PATH" ]; then
    _RESOLVED=$(command -v "$0" 2>/dev/null || true)
    [ -n "$_RESOLVED" ] && _SELF_PATH="$_RESOLVED"
fi
if [ ! -f "$_SELF_PATH" ]; then
    istore_err "Error: cannot locate installer file '$0'."
    exit 1
fi

istore_detect_arch() {
    _ida_raw=$(uname -m 2>/dev/null || echo "unknown")
    case "$_ida_raw" in
        x86_64|amd64)
            HOST_ARCH="amd64"
            ;;
        aarch64|arm64)
            HOST_ARCH="arm64"
            ;;
        *)
            HOST_ARCH="$_ida_raw"
            ;;
    esac
}

istore_verify_sha256() {
    _ivs_file="$1"
    _ivs_expected="$2"
    case "$_ivs_expected" in
        ""|"@@"*"@@")
            istore_err "Error: embedded payload SHA256 metadata is missing."
            return 1
            ;;
    esac

    _ivs_actual=""
    if command -v sha256sum >/dev/null 2>&1; then
        _ivs_actual=$(sha256sum "$_ivs_file" 2>/dev/null | awk '{print $1}')
    elif command -v openssl >/dev/null 2>&1; then
        _ivs_actual=$(openssl dgst -sha256 "$_ivs_file" 2>/dev/null | awk '{print $NF}')
    else
        istore_err "Error: neither sha256sum nor openssl is available to verify payload integrity."
        return 1
    fi

    if [ "$_ivs_actual" != "$_ivs_expected" ]; then
        istore_err "Error: payload SHA256 mismatch! expected=${_ivs_expected} actual=${_ivs_actual}"
        return 1
    fi
    return 0
}

istore_detect_arch
if [ "$FORCE_ARCH" -ne 1 ]; then
    case "$CUBEX_RUN_ARCH" in
        ""|"@@"*"@@")
            ;;
        *)
            if [ "$HOST_ARCH" != "$CUBEX_RUN_ARCH" ]; then
                istore_err "Error: architecture mismatch (installer=${CUBEX_RUN_ARCH}, host=${HOST_ARCH} / $(uname -m))."
                exit 1
            fi
            ;;
    esac
fi

_ARCHIVE_LINE=$(awk '/^__ARCHIVE_BELOW__$/ {print NR + 1; exit 0}' "$_SELF_PATH" 2>/dev/null || true)
case "$_ARCHIVE_LINE" in
    ""|*[!0-9]*)
        istore_err "Error: invalid .run archive (missing __ARCHIVE_BELOW__ marker)."
        exit 1
        ;;
esac

_TMP_WORK="/tmp/cubex_istore_run_$$"
trap 'rm -rf "$_TMP_WORK" 2>/dev/null || true' EXIT INT TERM
mkdir -p "$_TMP_WORK"

_PAYLOAD_TGZ="${_TMP_WORK}/payload.tar.gz"
tail -n +"$_ARCHIVE_LINE" "$_SELF_PATH" > "$_PAYLOAD_TGZ"
if [ ! -s "$_PAYLOAD_TGZ" ]; then
    istore_err "Error: extracted payload archive is empty."
    exit 1
fi

istore_verify_sha256 "$_PAYLOAD_TGZ" "$CUBEX_PAYLOAD_SHA256"

if [ "$ACTION_MODE" = "check" ]; then
    istore_msg "OK: CubeX iStoreOS .run verified"
    istore_msg "  Version : ${CUBEX_RUN_VERSION}"
    istore_msg "  Arch    : ${CUBEX_RUN_ARCH} (host: ${HOST_ARCH})"
    istore_msg "  SHA256  : ${CUBEX_PAYLOAD_SHA256}"
    if command -v tar >/dev/null 2>&1; then
        tar -tzf "$_PAYLOAD_TGZ" | head -n 20
    fi
    exit 0
fi

if [ "$ACTION_MODE" = "extract" ]; then
    [ -n "$EXTRACT_DIR" ] || { istore_err "Error: --extract requires a directory path."; exit 1; }
    mkdir -p "$EXTRACT_DIR"
    tar -xzf "$_PAYLOAD_TGZ" -C "$EXTRACT_DIR"
    istore_msg "Extracted CubeX payload to ${EXTRACT_DIR}"
    exit 0
fi

if [ "$(id -u)" -ne 0 ]; then
    istore_err "Error: installation requires root privileges."
    exit 1
fi

case "$APP_PORT" in
    ""|*[!0-9]*)
        istore_err "Error: invalid port '$APP_PORT'."
        exit 1
        ;;
esac

_STAGE_DIR="${_TMP_WORK}/stage"
mkdir -p "$_STAGE_DIR"
tar -xzf "$_PAYLOAD_TGZ" -C "$_STAGE_DIR"

if [ ! -s "${_STAGE_DIR}/bin/cubexd" ]; then
    istore_err "Error: payload missing bin/cubexd executable."
    exit 1
fi

istore_msg "========================================================================"
istore_msg "CubeX iStoreOS / OpenWrt Installer (${CUBEX_RUN_VERSION} · ${HOST_ARCH})"
istore_msg "========================================================================"

if [ -x /etc/init.d/cubex ]; then
    /etc/init.d/cubex stop >/dev/null 2>&1 || true
fi
pkill -x cubexd >/dev/null 2>&1 || killall cubexd >/dev/null 2>&1 || true

mkdir -p "${INSTALL_DIR}/bin" "${INSTALL_DIR}/etc/rules" "${INSTALL_DIR}/data"

cp -f "${_STAGE_DIR}/bin/cubexd" "${INSTALL_DIR}/bin/cubexd"
chmod 755 "${INSTALL_DIR}/bin/cubexd"

if [ -f "${_STAGE_DIR}/bin/cubex" ]; then
    cp -f "${_STAGE_DIR}/bin/cubex" "${INSTALL_DIR}/bin/cubex"
    chmod 755 "${INSTALL_DIR}/bin/cubex"
fi

if [ -f "${_STAGE_DIR}/meta.json" ]; then
    cp -f "${_STAGE_DIR}/meta.json" "${INSTALL_DIR}/meta.json"
    chmod 644 "${INSTALL_DIR}/meta.json"
fi

if [ -d "${_STAGE_DIR}/etc/rules" ]; then
    cp -rf "${_STAGE_DIR}/etc/rules/"* "${INSTALL_DIR}/etc/rules/" 2>/dev/null || true
fi

if [ -f "${_STAGE_DIR}/data/config.ir.json" ] && [ ! -s "${INSTALL_DIR}/data/config.ir.json" ]; then
    cp -f "${_STAGE_DIR}/data/config.ir.json" "${INSTALL_DIR}/data/config.ir.json"
    chmod 644 "${INSTALL_DIR}/data/config.ir.json"
fi

if [ -f "${_STAGE_DIR}/uninstall.sh" ]; then
    cp -f "${_STAGE_DIR}/uninstall.sh" "${INSTALL_DIR}/uninstall.sh"
    chmod 755 "${INSTALL_DIR}/uninstall.sh"
fi

mkdir -p /usr/bin
ln -sf "${INSTALL_DIR}/bin/cubex" /usr/bin/cubex 2>/dev/null || cp -f "${INSTALL_DIR}/bin/cubex" /usr/bin/cubex 2>/dev/null || true
chmod 755 /usr/bin/cubex 2>/dev/null || true
_LOCAL_BIN_CREATED=0
if [ -d /usr/local/bin ]; then
    ln -sf "${INSTALL_DIR}/bin/cubex" /usr/local/bin/cubex 2>/dev/null || true
    _LOCAL_BIN_CREATED=1
fi

istore_msg "[1/5] Tuning host kernel network forwarding and TUN device..."
if [ ! -c /dev/net/tun ]; then
    mkdir -p /dev/net 2>/dev/null || true
    mknod /dev/net/tun c 10 200 2>/dev/null || true
    chmod 666 /dev/net/tun 2>/dev/null || true
fi
modprobe tun >/dev/null 2>&1 || true

mkdir -p /etc/sysctl.d 2>/dev/null || true
cat <<'EOF' > /etc/sysctl.d/99-cubex.conf
net.ipv4.ip_forward=1
net.ipv4.conf.all.rp_filter=0
net.ipv4.conf.default.rp_filter=0
EOF
sysctl -w net.ipv4.ip_forward=1 >/dev/null 2>&1 || true
sysctl -w net.ipv4.conf.all.rp_filter=0 >/dev/null 2>&1 || true
sysctl -w net.ipv4.conf.default.rp_filter=0 >/dev/null 2>&1 || true

_NFT_CREATED=0
if command -v uci >/dev/null 2>&1; then
    if [ "$(uci -q get firewall.@defaults[0].flow_offloading 2>/dev/null || true)" = "1" ] || \
       [ "$(uci -q get firewall.@defaults[0].flow_offloading_hw 2>/dev/null || true)" = "1" ]; then
        mkdir -p /etc/nftables.d 2>/dev/null || true
        cat <<'EOF' > /etc/nftables.d/10-cubex-offload-exempt.nft
chain cubex_flow_exempt {
    type filter hook forward priority -5; policy accept;
    ip daddr 198.18.0.0/15 counter return
    ip saddr 198.18.0.0/15 counter return
}
EOF
        _NFT_CREATED=1
        nft insert rule inet fw4 forward ip daddr 198.18.0.0/15 counter return 2>/dev/null || true
        nft insert rule inet fw4 forward ip saddr 198.18.0.0/15 counter return 2>/dev/null || true
        /etc/init.d/firewall reload >/dev/null 2>&1 || true
    fi
fi

_TOTAL_MEM_KB=$(awk '/MemTotal/{print $2; exit}' /proc/meminfo 2>/dev/null || echo "524288")
case "$_TOTAL_MEM_KB" in
    ""|*[!0-9]*) _TOTAL_MEM_KB=524288 ;;
esac
if [ "$_TOTAL_MEM_KB" -le 600000 ]; then
    _GOMEMLIMIT="120MiB"
    _GOGC="50"
elif [ "$_TOTAL_MEM_KB" -le 1500000 ]; then
    _GOMEMLIMIT="256MiB"
    _GOGC="80"
else
    _GOMEMLIMIT="512MiB"
    _GOGC="100"
fi

istore_msg "[2/5] Installing procd daemon service (/etc/init.d/cubex)..."
cat <<EOF > /etc/init.d/cubex
#!/bin/sh /etc/rc.common
START=95
STOP=10
USE_PROCD=1

PROG="${INSTALL_DIR}/bin/cubexd"
WORKDIR="${INSTALL_DIR}"
LISTEN_PORT="${APP_PORT}"
EOF
cat <<'EOF' >> /etc/init.d/cubex

start_service() {
    _mem_kb=$(awk '/MemTotal/{print $2; exit}' /proc/meminfo 2>/dev/null)
    [ -z "$_mem_kb" ] && _mem_kb=524288
    if [ "$_mem_kb" -le 600000 ]; then
        _mem_limit="120MiB"
        _gogc_val="50"
    elif [ "$_mem_kb" -le 1500000 ]; then
        _mem_limit="256MiB"
        _gogc_val="80"
    else
        _mem_limit="512MiB"
        _gogc_val="100"
    fi

    if [ ! -c /dev/net/tun ]; then
        mkdir -p /dev/net 2>/dev/null || true
        mknod /dev/net/tun c 10 200 2>/dev/null || true
        chmod 666 /dev/net/tun 2>/dev/null || true
    fi

    procd_open_instance
    procd_set_param command "$PROG" -dir "$WORKDIR" -listen ":${LISTEN_PORT}"
    procd_set_param env GOMEMLIMIT="$_mem_limit" GOGC="$_gogc_val" GODEBUG="madvdontneed=1" TZ="Asia/Shanghai" CUBEX_SUPERVISED="1"
    procd_set_param respawn 3600 5 0
    procd_set_param limits nofile="65535 65535"
    procd_set_param stdout 1
    procd_set_param stderr 1
    procd_close_instance
}

stop_service() {
    pkill -x mihomo >/dev/null 2>&1 || killall mihomo >/dev/null 2>&1 || true
    pkill -x sing-box >/dev/null 2>&1 || killall sing-box >/dev/null 2>&1 || true
}

service_triggers() {
    procd_add_reload_trigger "network" "firewall"
}
EOF
chmod 755 /etc/init.d/cubex

istore_msg "[3/5] Installing LuCI 21.02+ menu, rpcd ACL, and dashboard redirect..."
mkdir -p /usr/share/luci/menu.d /usr/share/rpcd/acl.d /www/luci-static/resources/view/cubex

cat <<'EOF' > /usr/share/luci/menu.d/luci-app-cubex.json
{
  "admin/services/cubex": {
    "title": "CubeX",
    "order": 60,
    "action": {
      "type": "view",
      "path": "cubex/dashboard"
    },
    "depends": {
      "acl": [ "luci-app-cubex" ]
    }
  }
}
EOF
chmod 644 /usr/share/luci/menu.d/luci-app-cubex.json

cat <<'EOF' > /usr/share/rpcd/acl.d/luci-app-cubex.json
{
  "luci-app-cubex": {
    "description": "Grant UCI and service access for CubeX LuCI menu",
    "read": {
      "ubus": {
        "service": [ "list" ]
      },
      "file": {
        "/etc/init.d/cubex": [ "exec" ]
      }
    },
    "write": {
      "ubus": {
        "service": [ "signal" ]
      }
    }
  }
}
EOF
chmod 644 /usr/share/rpcd/acl.d/luci-app-cubex.json

cat <<EOF > /www/luci-static/resources/view/cubex/dashboard.js
'use strict';
'require view';

return view.extend({
	render: function () {
		var targetUrl = window.location.protocol + '//' + window.location.hostname + ':${APP_PORT}/';
		return E('div', { 'class': 'cbi-map' }, [
			E('h2', {}, _('CubeX Gateway Console')),
			E('div', { 'class': 'cbi-section' }, [
				E('p', {}, _('CubeX Web Dashboard runs on dedicated port :${APP_PORT}.')),
				E('a', {
					'class': 'cbi-button cbi-button-apply',
					'href': targetUrl,
					'target': '_blank',
					'rel': 'noopener noreferrer'
				}, _('Open CubeX Console (:${APP_PORT})'))
			])
		]);
	},
	handleSaveApply: null,
	handleSave: null,
	handleReset: null
});
EOF
chmod 644 /www/luci-static/resources/view/cubex/dashboard.js

rm -rf /tmp/luci-indexcache* /tmp/luci-modulecache/* 2>/dev/null || true
if [ -x /etc/init.d/rpcd ]; then
    /etc/init.d/rpcd reload >/dev/null 2>&1 || true
fi
if [ -x /etc/init.d/uhttpd ]; then
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || true
fi

istore_msg "[4/5] Updating /etc/sysupgrade.conf and writing install.manifest..."
_SYSUP_TMP="${_TMP_WORK}/sysupgrade.conf"
if [ -f /etc/sysupgrade.conf ]; then
    awk '
        /^# BEGIN CUBEX$/ { skip=1; next }
        /^# END CUBEX$/ { skip=0; next }
        skip { next }
        { print }
    ' /etc/sysupgrade.conf > "$_SYSUP_TMP"
else
    : > "$_SYSUP_TMP"
fi

cat <<EOF >> "$_SYSUP_TMP"
# BEGIN CUBEX
${INSTALL_DIR}/data
${INSTALL_DIR}/etc
${INSTALL_DIR}/install.manifest
${INSTALL_DIR}/uninstall.sh
/etc/init.d/cubex
/etc/sysctl.d/99-cubex.conf
/usr/share/luci/menu.d/luci-app-cubex.json
/usr/share/rpcd/acl.d/luci-app-cubex.json
/www/luci-static/resources/view/cubex/dashboard.js
# END CUBEX
EOF
mv -f "$_SYSUP_TMP" /etc/sysupgrade.conf
chmod 644 /etc/sysupgrade.conf 2>/dev/null || true

cat <<EOF > "${INSTALL_DIR}/install.manifest"
VERSION=${CUBEX_RUN_VERSION}
ARCH=${HOST_ARCH}
INSTALL_DIR=${INSTALL_DIR}
APP_PORT=${APP_PORT}
FILE=/etc/init.d/cubex
FILE=/usr/share/luci/menu.d/luci-app-cubex.json
FILE=/usr/share/rpcd/acl.d/luci-app-cubex.json
FILE=/www/luci-static/resources/view/cubex/dashboard.js
DIR=/www/luci-static/resources/view/cubex
FILE=/usr/bin/cubex
FILE=/etc/sysctl.d/99-cubex.conf
EOF
if [ "$_LOCAL_BIN_CREATED" -eq 1 ]; then
    printf 'FILE=/usr/local/bin/cubex\n' >> "${INSTALL_DIR}/install.manifest"
fi
if [ "$_NFT_CREATED" -eq 1 ]; then
    printf 'FILE=/etc/nftables.d/10-cubex-offload-exempt.nft\n' >> "${INSTALL_DIR}/install.manifest"
fi
chmod 644 "${INSTALL_DIR}/install.manifest"

istore_msg "[5/5] Enabling and starting procd service..."
/etc/init.d/cubex enable >/dev/null 2>&1 || true
/etc/init.d/cubex restart >/dev/null 2>&1 || /etc/init.d/cubex start >/dev/null 2>&1 || true

_WAIT_ALIVE=0
_TRY=0
while [ "$_TRY" -lt 15 ]; do
    if command -v wget >/dev/null 2>&1 && wget -q -T 2 -O - "http://127.0.0.1:${APP_PORT}/api/health" >/dev/null 2>&1; then
        _WAIT_ALIVE=1
        break
    elif command -v curl >/dev/null 2>&1 && curl -fsS -m 2 "http://127.0.0.1:${APP_PORT}/api/health" >/dev/null 2>&1; then
        _WAIT_ALIVE=1
        break
    fi
    sleep 1
    _TRY=$((_TRY + 1))
done

istore_msg "========================================================================"
if [ "$_WAIT_ALIVE" -eq 1 ]; then
    istore_msg "CubeX ${CUBEX_RUN_VERSION} installed and running on :${APP_PORT}"
else
    istore_msg "CubeX ${CUBEX_RUN_VERSION} installed (service starting via procd on :${APP_PORT})"
fi
istore_msg "  Install Dir : ${INSTALL_DIR}"
istore_msg "  procd Init  : /etc/init.d/cubex (enabled, respawn active)"
istore_msg "  LuCI Menu   : /usr/share/luci/menu.d/luci-app-cubex.json"
istore_msg "  Sysupgrade  : /etc/sysupgrade.conf updated"
istore_msg "  Uninstaller : sh ${INSTALL_DIR}/uninstall.sh"
istore_msg "========================================================================"
exit 0
__ARCHIVE_BELOW__
